import {STORIES,MAP_OBSERVATIONS,createStorySession} from './subject-exploration-model.js';
export function openStoryWorkshop({ui,document:doc=globalThis.document,random=Math.random}){
 return ui.workshop('문장으로 이야기 잇기',`<div class="subject-exploration" data-story-workshop><p>읽고 싶은 이야기를 골라, 처음부터 마지막까지 문장을 이어요.</p><div class="exploration-topics" role="group" aria-label="이야기 고르기">${STORIES.map(s=>`<button data-story-topic="${s.id}" aria-pressed="false">${s.title}</button>`).join('')}</div><p id="story-focus" class="caption"></p><h3 id="story-title"></h3><ol id="story-complete" class="story-complete" aria-label="이어 붙인 이야기"></ol><div id="story-choices" class="subject-choices"></div><section id="story-reflection" hidden><h3 id="story-question"></h3><div id="story-reflection-choices" class="subject-choices"></div></section><p id="subject-feedback" class="exploration-feedback" role="status" aria-live="polite"></p><div class="exploration-actions"><button id="story-restart" class="secondary">이 이야기 처음부터</button><button id="story-another" class="primary" hidden>다른 이야기 고르기</button></div><p class="caption">이야기를 바꿔도 하던 곳이 남아요. 창을 닫으면 처음부터 시작해요.</p></div>`,()=>{
  const root=doc.querySelector('[data-story-workshop]'),model=createStorySession(random),$=id=>doc.getElementById(id);let alive=true;
  function render(focus){if(!alive)return;const s=model.snapshot(),story=model.story;$('story-title').textContent=story.title;$('story-focus').textContent=story.focus+' · '+s.index+' / '+story.sentences.length+'문장';root.querySelectorAll('[data-story-topic]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.storyTopic===s.id)));
   $('story-complete').replaceChildren(...story.sentences.slice(0,s.index).map(text=>{const li=doc.createElement('li');li.textContent=text;return li;}));
   $('story-choices').replaceChildren(...s.order.map(index=>{const b=doc.createElement('button');b.dataset.story=String(index);b.textContent=story.sentences[index];b.disabled=index<s.index;return b;}));$('story-choices').hidden=s.complete;$('story-reflection').hidden=!s.complete;$('story-another').hidden=!s.complete;
   $('story-question').textContent=story.question;$('story-reflection-choices').replaceChildren(...story.choices.map((text,index)=>{const b=doc.createElement('button');b.textContent=text;b.dataset.storyReflection=String(index);b.setAttribute('aria-pressed',String(s.reflection===index));return b;}));$('subject-feedback').textContent=s.feedback;
   if(focus==='next'){const target=s.complete?root.querySelector('[data-story-reflection]'):[...root.querySelectorAll('[data-story]')].find(b=>!b.disabled);target?.focus();}else if(focus==='reflection')root.querySelector(`[data-story-reflection="${s.reflection}"]`)?.focus();
  }
  function click(e){if(!alive)return;const b=e.target.closest('button');if(!b||!root.contains(b)||b.disabled)return;if(b.dataset.storyTopic){model.select(b.dataset.storyTopic);render();}else if(b.dataset.story!==undefined){model.choose(Number(b.dataset.story));render('next');}else if(b.dataset.storyReflection!==undefined){model.reflect(Number(b.dataset.storyReflection));render('reflection');}else if(b.id==='story-restart'){model.restart();render('next');}else if(b.id==='story-another')root.querySelector('[data-story-topic]')?.focus();}
  root.addEventListener('click',click);render();return()=>{alive=false;root.removeEventListener('click',click);};
 },{kind:'school-workshop story-workshop'});
}
export function openMapWorkshop({ui,document:doc=globalThis.document}){
 return ui.workshop('세계지도에서 발견하기',`<div class="subject-exploration" data-map-workshop><p>지도를 보며 궁금한 질문을 하나씩 골라요. 힌트를 펼쳐도 괜찮아요.</p><div class="exploration-topics" role="group" aria-label="지도에서 살펴볼 것">${MAP_OBSERVATIONS.map(q=>`<button data-map-topic="${q.id}" aria-pressed="false">${q.title}</button>`).join('')}</div><div class="map-exploration-layout"><section class="map-observation" aria-label="지도 관찰 질문"><p id="map-progress" class="caption"></p><h3 id="map-question"></h3><div id="map-choices" class="subject-choices"></div><button id="map-hint" class="secondary" aria-expanded="false" aria-controls="map-hint-text">지도에서 찾을 단서</button><p id="map-hint-text" hidden></p><p id="map-feedback" class="exploration-feedback" role="status" aria-live="polite"></p><button id="map-next" class="primary" hidden>다음 발견</button></section><section aria-label="세계지도"><div class="map-study-tools"><label>지도 크기 <select id="world-map-scale"><option value="100">100%</option><option value="150">150%</option><option value="200">200%</option></select></label><span>북쪽은 위 · 점선은 적도</span></div><div id="map-viewport" class="world-map-study" tabindex="0" aria-label="세계지도. 확대한 지도는 손가락으로 밀거나 방향키로 스크롤해요"><div id="map-surface" class="map-surface"><img id="world-map-study-image" src="./school/maps/world-map-ko-2048.png" alt="아시아·유럽·아프리카·북아메리카·남아메리카·오세아니아·남극과 적도. 초록은 육지, 파랑은 바다예요"><span id="map-spot" class="map-spot" hidden aria-hidden="true"></span></div></div><p class="caption">나라의 경계선은 표시하지 않았어요. 확대하면 지도를 옆과 아래로 밀어 볼 수 있어요.</p></section></div><details><summary>지도 자료와 더 알아보기</summary><p>Natural Earth 육지 자료 · Equal Earth 도법. 둥근 지구를 평면에 옮겨 그렸어요. 관찰 질문과 설명은 도름마을에서 새로 썼어요.</p><a href="https://www.naturalearthdata.com/about/terms-of-use/" target="_blank" rel="noopener noreferrer">지도 자료 이용 안내</a></details><p class="caption">시간 제한과 점수는 없어요. 창을 닫으면 발견 기록은 처음부터 시작해요.</p></div>`,()=>{
  const root=doc.querySelector('[data-map-workshop]'),$=id=>doc.getElementById(id),states=MAP_OBSERVATIONS.map(()=>({selected:null,hint:false,reviewed:false}));let index=0,alive=true;
  function spot(){const q=MAP_OBSERVATIONS[index],show=states[index].hint&&q.spot;$('map-spot').hidden=!show;if(show){$('map-spot').style.left=q.spot.x+'%';$('map-spot').style.top=q.spot.y+'%';}}
  function render(){const q=MAP_OBSERVATIONS[index],s=states[index],correct=s.selected===q.answer,count=states.filter(v=>v.reviewed).length;root.querySelectorAll('[data-map-topic]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mapTopic===q.id)));$('map-progress').textContent=`살펴본 발견 ${count} / ${MAP_OBSERVATIONS.length}`;$('map-question').textContent=q.question;$('map-choices').replaceChildren(...q.choices.map((text,i)=>{const b=doc.createElement('button');b.textContent=text;b.dataset.mapChoice=String(i);b.setAttribute('aria-pressed',String(s.selected===i));return b;}));$('map-hint').setAttribute('aria-expanded',String(s.hint));$('map-hint').textContent=s.hint?'단서 접기':'지도에서 찾을 단서';$('map-hint-text').hidden=!s.hint;$('map-hint-text').textContent=q.hint;$('map-feedback').textContent=s.selected===null?'지도를 천천히 보고 골라요.':correct?q.explanation+(count===MAP_OBSERVATIONS.length?' 네 가지 발견을 모두 살펴봤어요! 마음에 드는 곳을 다시 찾아봐요.':''):'지도에서 찾을 단서를 읽고 다시 살펴봐요. 틀려도 횟수 제한은 없어요.';$('map-next').hidden=!correct;$('map-next').textContent=index===MAP_OBSERVATIONS.length-1?'첫 발견 다시 보기':'다음 발견';spot();}
  const center=()=>{const q=MAP_OBSERVATIONS[index];if(!q.spot)return;const viewport=$('map-viewport'),surface=$('map-surface');viewport.scrollLeft=surface.clientWidth*q.spot.x/100-viewport.clientWidth/2;viewport.scrollTop=surface.clientHeight*q.spot.y/100-viewport.clientHeight/2;};
  function click(e){if(!alive)return;const b=e.target.closest('button');if(!b||!root.contains(b))return;if(b.dataset.mapTopic){index=MAP_OBSERVATIONS.findIndex(q=>q.id===b.dataset.mapTopic);render();center();}else if(b.dataset.mapChoice!==undefined){states[index].selected=Number(b.dataset.mapChoice);if(states[index].selected===MAP_OBSERVATIONS[index].answer)states[index].reviewed=true;render();root.querySelector(`[data-map-choice="${states[index].selected}"]`)?.focus();}else if(b.id==='map-hint'){states[index].hint=!states[index].hint;render();if(states[index].hint)center();}else if(b.id==='map-next'){index=(index+1)%MAP_OBSERVATIONS.length;render();root.querySelector('[data-map-choice]')?.focus();center();}}
  const scale=()=>{$('map-surface').style.width=$('world-map-scale').value+'%';center();};root.addEventListener('click',click);$('world-map-scale').addEventListener('change',scale);render();return()=>{alive=false;root.removeEventListener('click',click);$('world-map-scale')?.removeEventListener('change',scale);};
 },{kind:'school-workshop world-map-workshop'});
}
